CREATE TEMPORARY VIEW dwd_search_page_${grass_region_without_quote} AS
SELECT 
    local_date 
    ,grass_region
    ,user_id
    ,event_id 
    ,event_timestamp
    ,search_session_id
    ,global_session_id
    ,search_entrance
    ,search_mid
    ,rn_version
    ,platform
    ,app_version
    ,last_view_event_id
    ,IF(page_type IN ('global_search', 'search_in_pdp', 'search_prefill'), 'srp', page_type) AS page_type
    ,RANK() OVER (PARTITION BY local_date,grass_region,user_id, if(page_type IN ('global_search', 'search_in_pdp', 'search_prefill'), 'srp', page_type)
        ORDER BY event_timestamp) AS time_rank
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE 
    local_date = ${local_date}
    AND grass_region IN (${grass_region})
    AND operation = 'view'
    AND user_id > 0
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill', 'pre_search', 'search_suggest_page');

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_user_fv_${grass_region_without_quote} AS
SELECT
    local_date 
    ,grass_region
    ,user_id

    ,max(if(page_type = 'srp', event_id, NULL)) AS srp_fv_vid
    ,max(if(page_type = 'srp', search_mid, NULL)) AS srp_fv_search_mid
    ,max(if(page_type = 'srp', search_entrance, NULL)) AS srp_fv_search_entrance
    ,max(if(page_type = 'srp', last_view_event_id, NULL)) AS srp_fv_last_lvid
    ,max(if(page_type = 'srp', search_session_id, NULL)) AS srp_fv_search_session_id
    ,max(if(page_type = 'srp', global_session_id, NULL)) AS srp_fv_global_session_id
    ,max(if(page_type = 'srp', rn_version, NULL)) AS srp_fv_rn_version
    ,max(if(page_type = 'srp', platform, NULL)) AS srp_fv_platform
    ,max(if(page_type = 'srp', app_version, NULL)) AS srp_fv_app_version

    ,max(if(page_type = 'pre_search', event_id, NULL)) AS sdp_fv_vid
    ,max(if(page_type = 'pre_search', search_entrance, NULL)) AS sdp_fv_search_entrance
    ,max(if(page_type = 'pre_search', last_view_event_id, NULL)) AS sdp_fv_last_lvid

    ,max(if(page_type = 'search_suggest_page', event_id, NULL)) AS sup_fv_vid
    ,max(if(page_type = 'search_suggest_page', search_entrance, NULL)) AS sup_fv_search_entrance
    ,max(if(page_type = 'search_suggest_page', last_view_event_id, NULL)) AS sup_fv_last_lvid
FROM
    dwd_search_page_${grass_region_without_quote}
WHERE
    time_rank = 1
GROUP BY 1,2,3;

