/*+REPARTITION(500)*/
    page_type
    ,event_id
    ,userid as user_id
    ,if(last_view_event_id IS NULL ,concat('salt_',cast(rand() as string)), last_view_event_id) AS last_view_event_id
    ,pre_source.page_type as pre_souce_type_type
    ,if(last_view_civ_id IS NULL ,concat('salt_',cast(rand() as string)), last_view_civ_id) AS last_view_civ_id
