CREATE TEMPORARY VIEW dwd_all_search_event_id_${grass_region_without_quote} AS
SELECT 
    event_id
    ,userid AS user_id
    ,collect_set(page_type) AS page_type
FROM 
    traffic.shopee_traffic_dwd_view_hi__reg_s1_live
WHERE
    local_date = ${local_date}
    AND grass_region IN (${grass_region})
    AND userid > 0
    AND operation = 'view'
    AND page_type IN ('pre_search', 'search', 'search_suggest_page')
    AND event_id IS NOT NULL
GROUP BY event_id, userid;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_all_search_civ_id_${grass_region_without_quote} AS
SELECT 
    civ_id
    ,userid AS user_id
    ,collect_set(page_type) AS page_type
FROM 
    traffic.shopee_traffic_dwd_view_hi__reg_s1_live
WHERE
    local_date = ${local_date}
    AND grass_region IN (${grass_region})
    AND userid > 0
    AND operation = 'view'
    AND page_type IN ('pre_search', 'search', 'search_suggest_page')
    AND civ_id IS NOT NULL
