CREATE TEMPORARY VIEW dwd_attribute_search_page_${grass_region_without_quote} AS
SELECT 
    a.page_type AS page_type
    ,a.user_id AS user_id
    ,a.current_page AS current_page
    ,array_union(COALESCE(array(a.pre_souce_type_type), array()),array_union(COALESCE(b.page_type, array()) , COALESCE(c.page_type, array()))) AS source_page_types
    ,a.event_id AS event_id
FROM 
    dwd_platform_page_${grass_region_without_quote} a
    LEFT JOIN dwd_all_search_event_id_${grass_region_without_quote} b
        ON a.last_view_event_id = b.event_id
        AND a.user_id = b.user_id
    LEFT JOIN dwd_all_search_civ_id_${grass_region_without_quote} c
        ON a.last_view_civ_id = c.civ_id
        AND a.user_id = c.user_id
WHERE
    a.pre_souce_type_type IN ('pre_search', 'search', 'search_suggest_page')
    OR size(array_union(COALESCE(b.page_type, array()) , COALESCE(c.page_type, array()))) > 0
UNION ALL
SELECT
    'home' AS page_type
    ,d.user_id
    ,NULL AS current_page
    ,array(d.page_type) AS source_page_types
    ,e.event_id AS event_id
FROM
    dwd_platform_page_${grass_region_without_quote} d
    INNER JOIN dwd_platform_page_${grass_region_without_quote} e
        ON d.user_id = e.user_id
        AND (d.time_rank + 1) = e.time_rank
        AND d.page_type IN ('pre_search', 'search_suggest_page')
        AND e.page_type = 'home'
        AND e.last_view_event_id = 'PATH_ROOT_FIRST';

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_outflow_${grass_region_without_quote} AS
SELECT 
    user_id
    ,source_page_type 
    ,page_type
    ,to_json(named_struct('page_type', page_type, 'outflow_times', count(distinct event_id), 'current_page', COLLECT_SET(current_page))) AS outflow_info
FROM 
    dwd_attribute_search_page_${grass_region_without_quote}
    lateral view explode(source_page_types) as source_page_type 
GROUP BY user_id, source_page_type, page_type;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_outflow_res_${grass_region_without_quote} AS
SELECT 
    user_id
    ,COLLECT_SET(if(source_page_type = 'search', page_type, NULL)) AS srp_outflow_page
    ,COLLECT_SET(if(source_page_type = 'search', outflow_info, NULL)) AS srp_outflow_info
    ,COLLECT_SET(if(source_page_type = 'pre_search', page_type, NULL)) AS sdp_outflow_page
    ,COLLECT_SET(if(source_page_type = 'pre_search', outflow_info, NULL)) AS sdp_outflow_info
    ,COLLECT_SET(if(source_page_type = 'search_suggest_page', page_type, NULL)) AS sup_outflow_page
    ,COLLECT_SET(if(source_page_type = 'search_suggest_page', outflow_info, NULL)) AS sup_outflow_info
FROM 
    dws_search_outflow_${grass_region_without_quote}
GROUP BY user_id;


