    ,srp_outflow_page
    ,srp_outflow_info

    ,sdp_fv_vid
    ,sdp_fv_search_entrance
    ,sdp_fv_last_lvid
    ,sdp_outflow_page
    ,sdp_outflow_info
    
    ,sup_fv_vid
    ,sup_fv_search_entrance
    ,sup_fv_last_lvid
    ,sup_outflow_page
    ,sup_outflow_info
FROM
    dws_search_user_fv_${grass_region_without_quote} a
